const API=window.__HATCHABLE__?.api||'/api';const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const DESCRIPTION_CAPTION_COLORS={green:'#167C3A',red:'#B42318',blue:'#175CD3',yellow:'#8A5A00',purple:'#6941C6'};const DESCRIPTION_CAPTION_COLOR_NAMES={green:'Green',red:'Red',blue:'Blue',yellow:'Yellow',purple:'Purple'};const isDescriptionCaptionColor=value=>Object.values(DESCRIPTION_CAPTION_COLORS).includes(String(value||'').toUpperCase());let projects=[];let editing={project:null,sections:[],images:[],originalSectionIds:[]};let mediaState={project:null,sections:[],images:[]};let supabaseClient=null;let editorLoadToken=0;let editorSaving=false;let slugAutomatic=false;
function msg(el,text,error=false){if(!el)return;el.textContent=text;el.style.color=error?'#a53b35':''}
function cmsLoading(show,label='Processing…',scope){const host=scope||document.getElementById('editor');if(!host)return;let el=host.querySelector('#cmsLoadingOverlay');if(!el){el=document.createElement('div');el.id='cmsLoadingOverlay';el.innerHTML='<div class="cms-loading-card"><span class="cms-spinner" aria-hidden="true"></span><span class="cms-loading-label"></span></div>';host.appendChild(el)}el.querySelector('.cms-loading-label').textContent=label;el.classList.toggle('is-visible',!!show)}
function cmsToast(text){const host=document.getElementById('cmsToastHost')||(()=>{const h=document.createElement('div');h.id='cmsToastHost';document.body.appendChild(h);return h})();const toast=document.createElement('div');toast.className='cms-toast';toast.textContent=text;host.appendChild(toast);window.setTimeout(()=>{toast.classList.add('is-leaving');window.setTimeout(()=>toast.remove(),200)},2200)}
async function withCmsLoading(label,work){cmsLoading(true,label);try{return await work()}finally{cmsLoading(false)}}
async function initSupabase(){const cfg=await fetch(API+'/admin-config',{credentials:'include'}).then(async r=>{const d=await r.json();if(!r.ok)throw Error(d.error||'Unable to load authentication configuration.');return d});if(!window.supabase){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2';s.onload=resolve;s.onerror=()=>reject(Error('Unable to load Supabase authentication.'));document.head.appendChild(s)})}supabaseClient=window.supabase.createClient(cfg.url,cfg.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});const {data,error}=await supabaseClient.auth.getSession();if(error||!data?.session)throw Error('Please sign in to the admin panel.');return data.session}
async function api(path,opts={}){const headers=opts.body instanceof FormData?{}:{'Content-Type':'application/json'};const request=async token=>fetch(API+path,{...opts,credentials:'include',redirect:'manual',headers:{...headers,...(token?{Authorization:`Bearer ${token}`}:{}),...(opts.headers||{})}});let token='';if(supabaseClient){const sessionData=await supabaseClient.auth.getSession().catch(()=>null);token=sessionData?.data?.session?.access_token||'';}let r=await request(token);if(r.status===401&&supabaseClient){const refreshed=await supabaseClient.auth.refreshSession().catch(()=>null);const freshToken=refreshed?.data?.session?.access_token;if(freshToken)r=await request(freshToken);}let d={};try{d=await r.json()}catch{}if(r.status===401||r.type==='opaqueredirect'){location.replace('/admin/login/');throw Error('Your admin session could not be refreshed. Please sign in again.')}if(r.status===403)throw Error(d.error||'Admin access required.');if(!r.ok)throw Error(d.error||'Request failed.');return d}
async function initAuth(){try{await initSupabase();const session=await api('/admin-session');$('#authEmail').textContent=session.email||'Project owner';await loadProjects();}catch(e){if(!/Redirecting to admin sign-in/.test(e.message))$('#projectList').innerHTML=`<div class="panel">${esc(e.message||'Unable to load the admin panel.')}</div>`}}
$('#logoutBtn').onclick=async()=>{try{if(supabaseClient)await supabaseClient.auth.signOut()}finally{location.replace('/admin/login/')}};
async function reorderProjects(orderedIds){try{const result=await api('/admin-projects',{method:'PUT',body:JSON.stringify({action:'reorder',ordered_ids:orderedIds})});projects=Array.isArray(result.projects)?result.projects:projects;renderProjects();cmsToast('Case study order saved.');}catch(e){alert(e.message||'Unable to save the case study order.');await loadProjects()}}
function canReorderProjects(){return !($('#projectSearch').value||'').trim()&&$('#statusFilter').value==='all'}
function renderProjects(){const search=($('#projectSearch').value||'').toLowerCase();const filter=$('#statusFilter').value;const list=projects.filter(p=>(filter==='all'||p.status===filter)&&(`${p.title} ${p.category}`.toLowerCase().includes(search)));if(!list.length){$('#projectList').innerHTML='<div class="panel">No case studies match your search.</div>';return}const reorderEnabled=canReorderProjects();$('#projectList').innerHTML=list.map((p,index)=>{const published=p.status==='published';return `<div class="project-row" draggable="${reorderEnabled?'true':'false'}" data-project-id="${esc(p.id)}"><div class="project-image-frame"><img class="thumb" src="${esc(p.cover_image_url||'')}" alt=""></div><div class="project-content-frame"><div class="project-info-frame"><h3>${esc(p.title)}</h3><p>${esc(p.category)} · ${esc(p.duration||'')} · <span class="status ${published?'':'draft'}">${esc(p.status)}</span></p></div><div class="project-action-frame"><div class="project-actions"><span class="muted project-position" title="Current portfolio position">#${esc(index+1)}</span><!-- position controls removed; desktop drag-and-drop remains --><span class="project-drag-handle" title="Drag to reorder" aria-hidden="true">⋮⋮</span><button class="secondary preview-project" data-id="${esc(p.id)}">Preview</button><button class="${published?'secondary':'primary'} publish-toggle" data-id="${esc(p.id)}">${published?'Unpublish':'Publish'}</button><button class="secondary edit-project" data-id="${esc(p.id)}">Edit</button><button class="secondary manage-media" data-id="${esc(p.id)}">Media</button><button class="icon-btn duplicate-project" type="button" data-id="${esc(p.id)}" title="Duplicate case study" aria-label="Duplicate case study"><svg aria-hidden="true" viewBox="0 0 24 24" width="18" height="18" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M16 8V5.2C16 4.0799 16 3.51984 15.782 3.09202C15.5903 2.71569 15.2843 2.40973 14.908 2.21799C14.4802 2 13.9201 2 12.8 2H5.2C4.0799 2 3.51984 2 3.09202 2.21799C2.71569 2.40973 2.40973 2.71569 2.21799 3.09202C2 3.51984 2 4.0799 2 5.2V12.8C2 13.9201 2 14.4802 2.21799 14.908C2.40973 15.2843 2.71569 15.5903 3.09202 15.782C3.51984 16 4.0799 16 5.2 16H8M11.2 22H18.8C19.9201 22 20.4802 22 20.908 21.782C21.2843 21.5903 21.5903 21.2843 20.908 20.908C22 20.4802 22 19.9201 22 18.8V11.2C22 10.0799 22 9.51984 21.782 9.09202C21.5903 8.71569 21.2843 8.40973 20.908 8.21799C20.4802 8 19.9201 8 18.8 8H11.2C10.0799 8 9.51984 8 9.09202 8.21799C8.71569 8.40973 8.40973 8.71569 8.21799 9.09202 8 9.51984 8 10.0799 8 11.2V18.8C8 19.9201 8 20.4802 8.21799 20.908C8.40973 21.2843 8.71569 21.5903 9.09202 21.782C9.51984 22 10.0799 22 11.2 22Z" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></button><button class="icon-btn delete-project-icon" type="button" data-id="${esc(p.id)}" title="Delete Case Study" aria-label="Delete Case Study"><svg aria-hidden="true" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18M8 6V4h8v2m3 0-1 14H6L5 6m4 4v6m6-6v6"/></svg></button></div></div></div></div></div>`}).join('');document.querySelectorAll('.edit-project').forEach(b=>b.onclick=()=>openEditor(projects.find(p=>p.id===b.dataset.id)));document.querySelectorAll('.manage-media').forEach(b=>b.onclick=()=>openMediaForProject(b.dataset.id));document.querySelectorAll('.preview-project').forEach(b=>b.onclick=()=>previewProject(b.dataset.id));document.querySelectorAll('.duplicate-project').forEach(b=>b.onclick=()=>duplicateProject(b.dataset.id,b));document.querySelectorAll('.delete-project-icon').forEach(b=>b.onclick=()=>{const project=projects.find(x=>String(x.id)===String(b.dataset.id));void trashProject(b.dataset.id,b,project)});document.querySelectorAll('.publish-toggle').forEach(b=>b.onclick=()=>toggleProjectStatus(b.dataset.id));bindProjectReordering()}
function moveProjectByRemoved(){/* Reordering now uses desktop drag-and-drop only. */}
function bindProjectReordering(){document.querySelectorAll('.project-row[draggable="true"]').forEach(row=>{row.addEventListener('dragstart',e=>{row.classList.add('is-dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',row.dataset.projectId)});row.addEventListener('dragend',()=>row.classList.remove('is-dragging'));row.addEventListener('dragover',e=>{e.preventDefault();row.classList.add('is-drag-over');e.dataTransfer.dropEffect='move'});row.addEventListener('dragleave',()=>row.classList.remove('is-drag-over'));row.addEventListener('drop',e=>{e.preventDefault();row.classList.remove('is-drag-over');const sourceId=e.dataTransfer.getData('text/plain');const targetId=row.dataset.projectId;if(!sourceId||sourceId===targetId)return;const ids=projects.map(p=>String(p.id));const from=ids.indexOf(sourceId),to=ids.indexOf(targetId);if(from<0||to<0)return;ids.splice(from,1);const targetRect=row.getBoundingClientRect();const insertAfter=e.clientY>targetRect.top+targetRect.height/2;const adjustedTarget=ids.indexOf(targetId)+(insertAfter?1:0);ids.splice(adjustedTarget,0,sourceId);void reorderProjects(ids)})})}
async function toggleProjectStatus(id){const project=projects.find(p=>String(p.id)===String(id));if(!project)return;const next=project.status==='published'?'draft':'published';const action=next==='published'?'publish':'unpublish';if(!confirm(`${next==='published'?'Publish':'Unpublish'} “${project.title}”?`))return;try{await api('/admin-projects',{method:'PUT',body:JSON.stringify({id:project.id,status:next})});await loadProjects()}catch(e){alert(e.message||`Unable to ${action} case study.`)}}
async function previewProject(id){const project=projects.find(p=>String(p.id)===String(id));if(!project)return;try{const d=await api('/admin-preview',{method:'POST',body:JSON.stringify({project_id:project.id})});if(d.preview_url){const previewUrl=new URL(d.preview_url,location.origin);const opened=window.open(previewUrl.toString(),'_blank');if(opened)opened.opener=null;else location.href=previewUrl.toString()}else throw Error('Preview link was not returned.')}catch(e){alert(e.message||'Unable to create preview link.')}}
async function duplicateProject(id,button){const source=projects.find(p=>String(p.id)===String(id));if(!source||button?.disabled)return;if(!confirm(`Create a complete draft copy of “${source.title}”? The original will remain unchanged.`))return;const prior=button?.innerHTML;if(button){button.disabled=true;button.setAttribute('aria-busy','true');button.title='Duplicating…';button.innerHTML='<span class="duplicate-spinner" aria-hidden="true"></span>';}try{const copy=await api('/admin-duplicate-case-study',{method:'POST',body:JSON.stringify({id:source.id})});await loadProjects();const created=projects.find(p=>String(p.id)===String(copy.id));cmsToast('Case study duplicated successfully. Your new draft is ready to edit.');if(created)await openEditor(created);else if(copy.id)await openEditor(copy);else throw Error('Copy was created but its editor record could not be loaded.')}catch(e){alert(e.message||'Unable to duplicate this case study. No changes were made to the original project.')}finally{if(button){button.disabled=false;button.removeAttribute('aria-busy');button.title='Duplicate Case Study';button.innerHTML=prior||'⧉'}}}
function chooseDeleteAction(title,description){return new Promise(resolve=>{let dialog=document.getElementById('caseStudyDeleteChoice');if(!dialog){dialog=document.createElement('dialog');dialog.id='caseStudyDeleteChoice';dialog.className='cms-confirm-dialog';dialog.innerHTML='<div class="confirm-content"><div class="eyebrow">CASE STUDY MANAGEMENT</div><h2 class="confirm-title"></h2><p class="confirm-description"></p><div class="confirm-actions"><button type="button" class="secondary confirm-cancel">Cancel</button><button type="button" class="secondary confirm-trash">Move to Trash</button><button type="button" class="danger confirm-permanent">Delete Permanently</button></div></div>';document.body.appendChild(dialog)}dialog.querySelector('.confirm-title').textContent=title;dialog.querySelector('.confirm-description').textContent=description;const finish=value=>{dialog.close();resolve(value)};dialog.querySelector('.confirm-cancel').onclick=()=>finish('cancel');dialog.querySelector('.confirm-trash').onclick=()=>finish('trash');dialog.querySelector('.confirm-permanent').onclick=()=>finish('permanent');dialog.oncancel=e=>{e.preventDefault();finish('cancel')};dialog.showModal()})}
async function trashProject(id,button,knownProject){const targetId=String(id??'').trim();if(button?.disabled)return;if(!targetId){alert('This case study has no database ID in the CMS request. Refresh the case study list and retry.');return;}let p=knownProject||projects.find(x=>String(x.id)===targetId);if(!p){try{const fresh=await api('/admin-projects');projects=Array.isArray(fresh)?fresh:[];p=projects.find(x=>String(x.id)===targetId);}catch(error){alert(error.message||'Could not refresh case study details. The deletion request was not sent.');return;}}const title=p?.title||$('#projectForm')?.elements?.title?.value||'this case study';const choice=await chooseDeleteAction('Delete Case Study',`Choose how to delete “${title}”. Move it to Trash to restore it later, or permanently delete it now.`);if(choice==='cancel')return;if(choice==='permanent'&&!confirm('Permanently Delete Case Study? This cannot be undone. The case study and exclusively owned media will be removed.'))return;if(button)button.disabled=true;try{if(choice==='trash'){await api('/admin-trash',{method:'POST',body:JSON.stringify({id:targetId})});cmsToast('Case study moved to Trash successfully.')}else{await api('/admin-trash',{method:'DELETE',body:JSON.stringify({id:targetId,confirm:true})});cmsToast('Case study permanently deleted.')}await loadProjects();await loadTrash();if($('#editor')?.open&&String($('#projectForm').elements.id.value)===targetId){editorLoadToken++;$('#editor').close()}}catch(e){alert(e.message||'Unable to delete case study.')}finally{if(button)button.disabled=false}}
async function loadTrash(){try{const rows=await api('/admin-trash');const count=$('#trashCount');if(count){count.textContent=rows.length;count.hidden=!rows.length}const empty=$('#emptyTrash');if(empty)empty.disabled=!rows.length||empty.dataset.busy==='true';const host=$('#trashList');if(!host)return;if(!rows.length){host.innerHTML='<div class="panel">Trash is empty.</div>';return}host.innerHTML=rows.map(p=>{const previous=p.previous_status||'draft';const date=p.deleted_at?new Date(p.deleted_at).toLocaleString():'Deletion date unavailable';return '<div class="project-row trash-row"><img class="thumb" src="'+esc(p.cover_image_url||'/images/project-placeholder.svg')+'" alt=""><div><h3>'+esc(p.title||'Untitled case study')+'</h3><p>Original slug: '+esc(p.previous_slug||p.slug||'Unavailable')+' · Previously '+esc(previous)+' · Deleted '+esc(date)+'</p></div><div class="project-actions"><button class="secondary restore-trash" data-id="'+esc(p.id)+'">Restore</button><button class="danger permanent-trash" data-id="'+esc(p.id)+'">Delete permanently</button></div></div>'}).join('');host.querySelectorAll('.restore-trash').forEach(b=>b.onclick=()=>restoreTrash(b.dataset.id,b));host.querySelectorAll('.permanent-trash').forEach(b=>b.onclick=()=>permanentlyDeleteTrash(b.dataset.id,b))}catch(e){const host=$('#trashList');if(host)host.innerHTML='<div class="panel">'+esc(e.message||'Unable to load Trash.')+'</div>'}}
async function restoreTrash(id,button){if(button?.disabled)return;button.disabled=true;try{const result=await api('/admin-trash',{method:'PUT',body:JSON.stringify({id})});cmsToast(result.slug_changed?'Restored as Draft with a safe alternative slug.':'Case study restored as Draft.');await Promise.all([loadTrash(),loadProjects()])}catch(e){alert(e.message||'Unable to restore case study.')}finally{button.disabled=false}}
async function permanentlyDeleteTrash(id,button){if(button?.disabled)return;if(!confirm('Permanently Delete Case Study? This cannot be undone. Its exclusively owned media will also be removed.'))return;button.disabled=true;try{const result=await api('/admin-trash',{method:'DELETE',body:JSON.stringify({id,confirm:true})});cmsToast('Case study permanently deleted.');await loadTrash()}catch(e){alert(e.message||'Permanent deletion failed. The item remains in Trash if cleanup did not complete.')}finally{button.disabled=false}}
async function emptyTrash(){const button=$('#emptyTrash');if(!button||button.disabled||button.dataset.busy==='true')return;const rows=await api('/admin-trash');if(!rows.length){await loadTrash();return}if(!confirm('Empty Trash Permanently? You are about to permanently delete all '+rows.length+' case studies currently in Trash, including content and eligible media. This cannot be undone.'))return;button.disabled=true;button.dataset.busy='true';button.textContent='Emptying…';try{const result=await api('/admin-trash',{method:'DELETE',body:JSON.stringify({action:'empty',confirm:true})});await Promise.all([loadTrash(),loadProjects()]);if(result.failed?.length)alert('Empty Trash partially completed: '+result.deleted+' deleted, '+result.failed.length+' retained for retry.');else cmsToast('Trash emptied. '+result.deleted+' case studies permanently deleted.')}catch(e){alert(e.message||'Unable to empty Trash. Items not confirmed deleted remain available.')}finally{button.dataset.busy='false';button.textContent='Empty Trash';button.disabled=false;await loadTrash()}}
async function loadProjects(){try{projects=await api('/admin-projects');renderProjects();populateMediaProjects()}catch(e){$('#projectList').innerHTML=`<div class="panel">${esc(e.message)}</div>`}}
$('#projectSearch').oninput=renderProjects;$('#statusFilter').onchange=renderProjects;$('#refreshTrash').onclick=loadTrash;$('#emptyTrash').onclick=emptyTrash;
function switchTab(tab){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));$('#projectsTab').hidden=tab!=='projects';$('#mediaTab').hidden=tab!=='media';$('#aboutTab').hidden=tab!=='about';$('#trashTab').hidden=tab!=='trash';$('#pageTitle').textContent=tab==='media'?'Media':tab==='about'?'About & site':tab==='trash'?'Trash / Recycle Bin':'Case studies';$('#newProject').hidden=tab!=='projects';if(tab==='media'){populateMediaProjects();loadMedia()}if(tab==='about')loadSettings();if(tab==='trash')loadTrash()}
document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>switchTab(t.dataset.tab));
function populateMediaProjects(selected){const s=$('#mediaProject');const keep=selected||s.value;if(!projects.length){s.innerHTML='<option value="">No case studies found in Turso</option>';return}s.innerHTML='<option value="">Select a case study…</option>'+projects.map(p=>`<option value="${esc(p.id)}">${esc(p.title)}</option>`).join('');if(keep&&projects.some(p=>p.id===keep))s.value=keep}
function populateMediaSections(selected){const s=$('#mediaSection');if(!s)return;const sections=mediaState.sections||[];s.innerHTML='<option value="">Automatic section</option>'+sections.map(x=>`<option value="${esc(x.id)}">${esc(x.title||'Untitled section')}${x.asset_type?' · '+esc(typeLabel(x.asset_type)):''}</option>`).join('');if(selected&&sections.some(x=>String(x.id)===String(selected)))s.value=selected}
async function openMediaForProject(id){switchTab('media');populateMediaProjects(id);$('#mediaProject').value=id;await loadMedia()}
async function loadMedia(){const id=$('#mediaProject').value;if(!id){$('#mediaList').innerHTML='<div class="empty">Select a case study.</div>';return}try{mediaState=await api('/admin-media?project_id='+encodeURIComponent(id));populateMediaTypes();populateMediaSections();renderMedia()}catch(e){$('#mediaList').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
const UNIFIED_ASSET_TYPES=[['project_cover','Project Cover'],['case_study_hero','Case-study Hero'],['design_exploration','Design Exploration'],['project_overview','Project Overview'],['the_challenge','The Challenge'],['the_goal','The Goal'],['my_role','My Role'],['project_context','Project Context'],['research_overview','Research Overview'],['research_methods','Research Methods'],['research_findings','Research Findings'],['key_insights','Key Insights'],['user_personas','User Personas'],['user_needs','User Needs'],['problem_statement','Problem Statement'],['ideation','Ideation'],['information_architecture','Information Architecture'],['user_flow','User Flow'],['wireframing','Wireframing'],['low_fidelity_prototype','Low-Fidelity Prototype'],['high_fidelity_prototype','High-Fidelity Prototype'],['heuristic_review','Heuristic Review'],['usability_testing','Usability Testing'],['design_decisions','Design Decisions'],['design_iteration','Design Iteration'],['design_refinement','Design Refinement'],['visual_design','Visual Design'],['design_system','Design System'],['accessibility','Accessibility'],['responsive_design','Responsive Design'],['final_solution','Final Solution'],['outcome','Outcome'],['learnings','Learnings'],['next_steps','Next Steps'],['sitemap','Sitemap'],['paper_wireframe','Paper Wireframe'],['digital_wireframe','Digital Wireframe'],['desktop_before_heuristic','Desktop Before Heuristic Review'],['desktop_after_heuristic','Desktop After Heuristic Review'],['mobile_before_heuristic','Mobile Before Heuristic Review'],['mobile_after_heuristic','Mobile After Heuristic Review'],['final_desktop_screens','Final Desktop Screens'],['final_tablet_screens','Final Tablet Screens'],['final_mobile_screens','Final Mobile Screens'],['hifi_desktop_onboarding','High-Fidelity Desktop Onboarding Flow'],['hifi_mobile_onboarding','High-Fidelity Mobile Onboarding Flow'],['research','Research'],['storyboard','Storyboard'],['wireframes_legacy','Wireframes (legacy)'],['mobile_final_ui','Mobile Final UI'],['web_final_ui','Web Final UI']];
function typeLabel(t){const hit=UNIFIED_ASSET_TYPES.find(x=>x[0]===t);if(hit)return hit[1];const legacy={cover:'Project Cover',hero:'Case-study Hero',marketing_sitemap:'Sitemap',marketing_paper_wireframe:'Paper Wireframe',marketing_digital_wireframe:'Digital Wireframe',marketing_desktop_before:'Desktop Before Heuristic Review',marketing_desktop_after:'Desktop After Heuristic Review',marketing_mobile_before:'Mobile Before Heuristic Review',marketing_mobile_after:'Mobile After Heuristic Review',marketing_desktop_final:'Final Desktop Screens',marketing_tablet_final:'Final Tablet Screens',marketing_mobile_final:'Final Mobile Screens',marketing_hifi_desktop:'High-Fidelity Desktop Onboarding Flow',marketing_hifi_mobile:'High-Fidelity Mobile Onboarding Flow',chinedu_persona:'Chinedu persona',fatima_persona:'Fatima persona',storyboard:'Storyboard',paper_wireframe:'Paper Wireframe',low_fi_wireframe:'Low-Fi wireframe',wireframes:'Wireframes (legacy)',usability_testing:'Usability Testing',mobile_final_ui:'Mobile Final UI',web_final_ui:'Web Final UI',research:'Research'};return legacy[t]||t}
function unifiedAssetOptions(){return UNIFIED_ASSET_TYPES.map(([value,label])=>({value,label}))}
function marketingAssetOptions(){return unifiedAssetOptions()}
function standardAssetOptions(){return unifiedAssetOptions()}
function populateMediaTypes(selected){const s=$('#mediaType');if(!s)return;const project=projects.find(p=>String(p.id)===String($('#mediaProject')?.value||''));const options=String(project?.slug||'')==='outsider-marketing-website'?marketingAssetOptions():standardAssetOptions();s.innerHTML=options.map(o=>`<option value="${esc(o.value)}">${esc(o.label)}</option>`).join('');if(selected&&options.some(o=>o.value===selected))s.value=selected;syncMediaSectionState()} 
function syncMediaSectionState(){const type=$('#mediaType')?.value||'';const section=$('#mediaSection');if(!section)return;const fixed=type==='cover'||type==='hero'||type==='project_cover'||type==='case_study_hero';section.disabled=fixed;if(fixed)section.value=''}
