function tusEncode(value){return btoa(unescape(encodeURIComponent(String(value))));}
async function directR2Upload(file,prep){const url=String(prep.signedUrl||'');if(!url)throw Error('R2 upload URL was not returned. Please retry the upload.');const contentType=String(prep.contentType||file.type||'application/octet-stream').toLowerCase();try{const response=await fetch(url,{method:'PUT',mode:'cors',credentials:'omit',cache:'no-store',headers:{'Content-Type':contentType},body:file});if(!response.ok)throw Error(`R2 upload failed (${response.status}). The signed upload request was rejected.`)}catch(error){if(error instanceof TypeError||String(error?.message||'').toLowerCase().includes('failed to fetch'))throw Error('R2 upload could not be reached by the browser. The R2 CORS and server-side upload checks are valid, so refresh this admin page and retry. If it still fails, check the browser Network tab for the PUT request to the R2 cloudflarestorage.com endpoint.');throw error}}
