// Card 4 color picker uses a document-level capture handler so the picker cannot be blocked by the editor's form/dialog event handling.
function openCard4ColorPicker(btn){if(!btn)return;const card=btn.closest?.('.section-card');if(!card)return;const i=Number(btn.dataset.card2),k=Number(btn.dataset.part);const cards=[...document.querySelectorAll('#sectionEditor .section-card')];const cardId=card.getAttribute('data-id');let secIndex=cards.indexOf(card);if(secIndex<0&&cardId){secIndex=editing.sections.findIndex(s=>String(s.id||'')===String(cardId))}const s=editing.sections[secIndex];if(!s)return;const cardItemsKey=(s.section_type==='card4'||s.type==='card4')?'card4_items':'card2_items';const part=s.metadata?.[cardItemsKey]?.[i]?.description_sections?.[k];const current=/^#[0-9A-Fa-f]{6}$/.test(part?.caption_color||'')?String(part.caption_color).toUpperCase():'#D84A3A';document.querySelectorAll('.card4-color-popover').forEach(p=>p.remove());const pop=document.createElement('div');pop.className='card4-color-popover';pop.setAttribute('role','dialog');pop.setAttribute('aria-label','Caption color picker');pop.innerHTML=`<div class="card4-picker-head"><strong>Caption color</strong><button type="button" class="card4-picker-close" aria-label="Close color picker">×</button></div><input class="card4-popup-color" type="color" value="${current}"><label>HEX code<input class="card4-popup-hex" type="text" inputmode="text" maxlength="7" value="${current}" placeholder="#D84A3A"></label><button type="button" class="primary card4-popup-ok">OK</button>`;pop.setAttribute('popover','manual');document.body.appendChild(pop);if(typeof pop.showPopover==='function')pop.showPopover();const rect=btn.getBoundingClientRect(),popupWidth=280,popupHeight=Math.min(250,window.innerHeight-24);let left=Math.min(rect.left,window.innerWidth-popupWidth-12),top=rect.bottom+8;if(top+popupHeight>window.innerHeight-12)top=Math.max(12,rect.top-popupHeight-8);pop.style.left=Math.max(12,left)+'px';pop.style.top=top+'px';const picker=pop.querySelector('.card4-popup-color'),hex=pop.querySelector('.card4-popup-hex');picker.oninput=()=>{hex.value=picker.value.toUpperCase()};hex.oninput=()=>{const v=hex.value.trim().toUpperCase();if(/^#[0-9A-Fa-f]{6}$/.test(v))picker.value=v};const closePicker=()=>pop.remove();pop.querySelector('.card4-picker-close').onclick=closePicker;pop.querySelector('.card4-popup-ok').onclick=()=>{const value=hex.value.trim().toUpperCase();if(!/^#[0-9A-Fa-f]{6}$/.test(value)){hex.focus();return}s.metadata={...(s.metadata||{})};s.metadata[cardItemsKey]=Array.isArray(s.metadata[cardItemsKey])?s.metadata[cardItemsKey]:[];const item=s.metadata[cardItemsKey][i]||{};item.description_sections=Array.isArray(item.description_sections)?item.description_sections:[];item.description_sections[k]={...(item.description_sections[k]||{}),caption_color:value};s.metadata[cardItemsKey][i]=item;btn.style.background=value;if(btn.nextElementSibling)btn.nextElementSibling.textContent=value;closePicker()};}
