function resolveEditorSection(card){
  if(!card)return null;
  const cardId=String(card.getAttribute('data-id')||'');
  if(cardId&&!cardId.startsWith('new-')){
    const byId=editing.sections.find(s=>String(s.id||s._id||'')===cardId);
    if(byId)return byId;
  }
  const cards=[...document.querySelectorAll('#sectionEditor .section-card')];
  const index=cards.indexOf(card);
  return index>=0?editing.sections[index]:null;
}
function syncNestedContentBlocks(card,s){
  s.metadata={...(s.metadata||{})};
  const blocks=[...card.querySelectorAll('.nested-content-item')].map((el,i)=>{
    const type=el.querySelector('.nested-content-type')?.value==='subsection'?'subsection':'quote';
    const prior=s.metadata.content_blocks?.[i]||{};
    const position=el.querySelector('.nested-content-block-position')?.value||prior.position||'after_body';
    if(type==='quote')return {id:String(prior.id||crypto.randomUUID()),type,position,text:el.querySelector('.nested-content-quote')?.value||'',author:el.querySelector('.nested-content-author')?.value||''};
    return {id:String(prior.id||crypto.randomUUID()),type,position,title:el.querySelector('.nested-content-title')?.value||'',body:el.querySelector('.nested-content-body')?.value||''};
  });
  s.metadata.content_blocks=blocks;
}
