// Asset type changes are already committed to editing.sections by the select's
// change handler in renderSections(). Do not read the rendered select values back
// during Save: a browser select falls back to its first option when its current
// value is not represented in the option list, which could silently turn a valid
// section asset type into "project_cover" during save.
document.addEventListener('change',e=>{const nestedType=e.target?.closest?.('.nested-content-type');if(nestedType&&nestedType.closest('#sectionEditor')){const card=nestedType.closest('.section-card'),s=resolveEditorSection(card);if(!s)return;syncNestedContentBlocks(card,s);const i=Number(nestedType.dataset.block);if(s.metadata.content_blocks[i]){const old=s.metadata.content_blocks[i];s.metadata.content_blocks[i]=nestedType.value==='subsection'?{id:old.id,type:'subsection',position:old.position,title:'',body:''}:{id:old.id,type:'quote',position:old.position,text:'',author:''};renderSections();}return;}if(!e.target.matches?.('.sec-type'))return;const card=e.target.closest('.section-card');const s=resolveEditorSection(card);if(!s)return;if(e.target.value==='subsection_showcase'){s.section_type='subsection_showcase';s.type='subsection_showcase';s.presentation_style='';s.metadata={...(s.metadata||{}),presentation_type:'subsection_showcase',showcase_layout:s.metadata?.showcase_layout||'grid',showcase_columns:[2,3,4].includes(Number(s.metadata?.showcase_columns))?Number(s.metadata.showcase_columns):2,showcase_subsections:Array.isArray(s.metadata?.showcase_subsections)?s.metadata.showcase_subsections:[]};renderSections()}});function syncAllEditorInputs(){
  const cards=[...document.querySelectorAll('#sectionEditor .section-card')];
  cards.forEach((card,si)=>{
    const s=editing.sections[si];
    if(!s)return;
    s.metadata={...(s.metadata||{})};
    const title=card.querySelector('.sec-title');
    const subtitle=card.querySelector('.sec-subtitle');
    const body=card.querySelector('.sec-body');
    const style=card.querySelector('.sec-presentation-style');
    const asset=card.querySelector('.sec-asset-type');
    const itemDisplay=card.querySelector('.sec-item-display');
    if(title)s.title=title.value;
    if(subtitle){s.subtitle=subtitle.value;s.sub_title=subtitle.value;s.metadata.subtitle=subtitle.value;}
    if(body){s.body=body.value;s.text=body.value;s.metadata.body=body.value;}
    if(style&&style.value){s.presentation_style=style.value;s.metadata.presentation_style=style.value;}
    if(asset&&asset.value){s.asset_type=asset.value;s.metadata.asset_type=asset.value;}
    if(itemDisplay){s.item_display=itemDisplay.value;s.metadata.item_display=itemDisplay.value;s.metadata.card_variant=itemDisplay.value;}
    // Sync nested showcase fields from the rendered editor before the main Save action.
    // These inputs update the in-memory section while typing, but previously were not
    // copied back from the DOM during Save, so title/description edits could remain
    // visible in the CMS while the database and public case study kept the old text.
    if(Array.isArray(s.metadata.showcase_subsections)){
      const nested=[...card.querySelectorAll('.showcase-subsection-editor')];
      nested.forEach((el,i)=>{
        const sub=s.metadata.showcase_subsections[i];
        if(!sub)return;
        const title=el.querySelector('.showcase-title');
        const description=el.querySelector('.showcase-description');
        if(title)sub.title=title.value;
        if(description)sub.description=description.value;
        const images=[...el.querySelectorAll('.showcase-image')];
        if(images.length){
          if(images[0].type==='checkbox'){
            sub.image_ids=images.filter(input=>input.checked).map(input=>String(input.value));
            sub.image_id=sub.image_ids[0]||'';
          }else{
            sub.image_id=String(images[0].value||'');
            sub.image_ids=sub.image_id?[sub.image_id]:[];
          }
        }
        const style=el.querySelector('.showcase-style');
        if(style)sub.presentation_style=style.value;
        const desktop=el.querySelector('.showcase-desktop');
        const tablet=el.querySelector('.showcase-tablet');
        const mobile=el.querySelector('.showcase-mobile');
        const width=el.querySelector('.showcase-single-width');
        if(desktop)sub.desktopColumns=Number(desktop.value)||1;
        if(tablet)sub.tabletColumns=Number(tablet.value)||1;
        if(mobile)sub.mobileColumns=Number(mobile.value)||1;
        if(width)sub.singleImageWidth=width.value==='body'?'body':'normal';
      });
    }
    // Also sync image-subsection fields so the main Save action cannot lose
    // nested title, visibility, divider, image, or layout changes.
    if(Array.isArray(s.metadata.image_subsections)){
      const nested=[...card.querySelectorAll('.image-subsection-editor')];
      nested.forEach((el,i)=>{
        const sub=s.metadata.image_subsections[i];
        if(!sub)return;
        const title=el.querySelector('.image-subsection-title');
        const header=el.querySelector('.image-subsection-header');
        const divider=el.querySelector('.image-subsection-divider');
        if(title)sub.title=title.value;
        if(header)sub.headerVisible=header.value==='show';
        if(divider)sub.dividerVisible=divider.value==='show';
        const images=[...el.querySelectorAll('.image-subsection-image')];
        if(images.length)sub.image_ids=images.filter(input=>input.checked).map(input=>String(input.value));
        const desktop=el.querySelector('.sub-image-layout-desktop');
        const tablet=el.querySelector('.sub-image-layout-tablet');
        const mobile=el.querySelector('.sub-image-layout-mobile');
        const width=el.querySelector('.sub-single-image-width');
        if(desktop)sub.desktopColumns=Number(desktop.value)||1;
        if(tablet)sub.tabletColumns=Number(tablet.value)||1;
        if(mobile)sub.mobileColumns=Number(mobile.value)||1;
        if(width)sub.singleImageWidth=width.value==='body'?'body':'normal';
      });
    }
    const isCard2=s.presentation_style==='card2'||s.section_type==='card2'||s.type==='card2';
    const isCard4=s.presentation_style==='card4'||s.section_type==='card4'||s.type==='card4';
    const isCard1=s.presentation_style==='card1'||s.section_type==='cards'||s.type==='cards';
    const isCard3=s.presentation_style==='card3'||s.section_type==='card3'||s.type==='card3';
    const isCard5=s.presentation_style==='card5'||s.section_type==='card5'||s.type==='card5';
    syncNestedContentBlocks(card,s);
    if(isCard2||isCard4)syncReusableCardInputs(card,s);
    if(isCard1||isCard3||s.section_type==='list'){
      s.items=[...card.querySelectorAll('.sec-item')].map(input=>input.value);
      s.metadata.items=[...s.items];
    }
    if(isCard5){
      s.items=[...card.querySelectorAll('.card5-content')].map(input=>input.value);
      s.metadata.items=[...s.items];
    }
    card.querySelectorAll('.prototype-label').forEach(el=>{const i=Number(el.dataset.prototype);if(Number.isInteger(i)&&s.metadata.prototype_buttons?.[i])s.metadata.prototype_buttons[i].label=el.value});
    card.querySelectorAll('.prototype-url').forEach(el=>{const i=Number(el.dataset.prototype);if(Number.isInteger(i)&&s.metadata.prototype_buttons?.[i])s.metadata.prototype_buttons[i].url=el.value});
    card.querySelectorAll('.prototype-type').forEach(el=>{const i=Number(el.dataset.prototype);if(Number.isInteger(i)&&s.metadata.prototype_buttons?.[i])s.metadata.prototype_buttons[i].type=el.value});
    card.querySelectorAll('.prototype-radius').forEach(el=>{const i=Number(el.dataset.prototype);if(Number.isInteger(i)&&s.metadata.prototype_buttons?.[i])s.metadata.prototype_buttons[i].radius=Math.max(0,Math.min(999,Number(el.value)||0))});
    card.querySelectorAll('.prototype-enabled').forEach(el=>{const i=Number(el.dataset.prototype);if(Number.isInteger(i)&&s.metadata.prototype_buttons?.[i])s.metadata.prototype_buttons[i].enabled=el.value==='true'});
    card.querySelectorAll('.prototype-open').forEach(el=>{const i=Number(el.dataset.prototype);if(Number.isInteger(i)&&s.metadata.prototype_buttons?.[i])s.metadata.prototype_buttons[i].openBehavior=el.value});
    const refiningBody=card.querySelector('.refining-body');
    const refiningHeading=card.querySelector('.refining-heading');
    if(refiningBody||refiningHeading){
      s.metadata.refining_design={...(s.metadata.refining_design||{})};
      if(refiningBody)s.metadata.refining_design.body=refiningBody.value;
      if(refiningHeading)s.metadata.refining_design.heading=refiningHeading.value;
      const items=[...card.querySelectorAll('.refining-item-text')].map(input=>input.value);
      if(items.length)s.metadata.refining_design.items=items;
    }
  });
}
